const fs=require('fs'),path=require('path'),assert=require('assert/strict'),{chromium}=require('playwright'),{execFileSync}=require('child_process');
const root=path.resolve(__dirname,'../../..'),assets=root+'/frontend/public/education/cat-html-v1',videos='/home/tibule12/Videos/AutoPromote Education - CAT HTML - Teacher Review - 2026-11-24',catalog=JSON.parse(fs.readFileSync(assets+'/catalog.json'));
